        t.toDouble(), n.toDouble(), ua.toDouble(), fa.toDouble(), th.toDouble(), sh.toDouble(), ft.toDouble(),
        ua2.toDouble(), fa2.toDouble(), th2.toDouble(), sh2.toDouble(), ft2.toDouble(), ut.toDouble(),
