            cuesRu = listOf("Согнуть другую ногу, колено к груди."), sanskrit = "эка-пада-ширша-сету-бандхасана", descriptionRu = "В мосту на голове сгибаем одну ногу и подтягиваем колено как можно ближе к груди.", descriptionEn = "In the head bridge, bend one leg and draw the knee as close to the chest as possible.",
