        Asana(id = "at_fbridge", nameRu = "Мост с опорой на лоб", nameEn = "Forehead-supported bridge", pose = p(330, 210, 160, 150, 220, 220, 180, 221, 221, 180, 158, 148, 300),
            cuesRu = listOf("Перекатиться на лоб, руки на бёдра. Осторожно с шеей."), sanskrit = "сету-бандхасана", descriptionRu = "Ладони у головы; помогая руками, перекатываемся на лоб, при необходимости слегка сгибая ноги. Руки кладём на бёдра. Требует большого внимания к шее.", descriptionEn = "Palms by the head; helping with the hands, roll onto the forehead, bending the legs slightly if needed. Place the hands on the thighs. Requires great attention to the neck.",
            figure = FigureRef("fbridge", false)),
        Asana(id = "at_matsya", nameRu = "Поза рыбы с вытянутыми конечностями", nameEn = "Fish pose with extended limbs", pose = p(35, 250, 150, 150, 150, 150, 60, 149, 149, 62, 148, 148, 350),
            cuesRu = listOf("Ягодицы на пол, голова на лбу, спина дугой; ноги и руки параллельно под острым углом."), sanskrit = "уттанапада-матсьясана", descriptionRu = "Упираясь ладонями, медленно опускаем ягодицы на пол, стараясь оставить голову на лбу, а не перекатиться на затылок; спина выгнута до предела. Прямые ноги вытягиваем под острым углом к полу, носки на себя, прямые руки параллельно ногам ладонями друг к другу.", descriptionEn = "Pressing with the palms, slowly lower the buttocks to the floor, trying to keep the head on the forehead rather than rolling onto the back of the head; the back arched to the limit. Extend the straight legs at an acute angle to the floor, toes toward you, straight arms parallel to the legs, palms facing each other.",
            figure = FigureRef("matsya", false)),
        Asana(id = "at_angstr", nameRu = "Угловое вытягивание в перевёрнутом наклоне", nameEn = "Angled stretch in the inverted bend", pose = p(0, 0, 72, 72, 78, 78, 170, 77, 77, 170, 70, 70, 0),
            cuesRu = listOf("Спина на полу, ноги вверх, большие пальцы в «кольцах» пальцев рук."), sanskrit = null, descriptionRu = "Спина, затылок и шея прижаты к полу. Поднимаем ноги и захватываем большие пальцы «кольцами» из пальцев рук. Ноги жёстко прямые, крестец на полу, лопатки прижаты; руками тянем носки на себя, таз уводим назад.", descriptionEn = "Back, back of the head and neck pressed to the floor. Raise the legs and grip the big toes with “rings” made of the fingers. Legs rigidly straight, sacrum on the floor, shoulder blades pressed down; pull the toes toward you with the hands, draw the pelvis back.",
            figure = FigureRef("angstr", false)),
        Asana(id = "at_baddhaup", nameRu = "Замкнутый перевёрнутый закрытый вытянутый наклон", nameEn = "Locked inverted closed extended bend", pose = p(0, 0, 62, 40, 50, 50, 140, 49, 49, 140, 60, 38, 0),
            cuesRu = listOf("За пятки, предплечьями давить на пальцы, сложиться в тазобедренных."), sanskrit = "баддха-урдхва-мукха-пащчимоттанасана", descriptionRu = "Подтянув стопы ближе, кладём ладони на подошвы и пальцами берёмся за пятки, предплечьями давим на пальцы ног. Отталкиваем таз от головы и складываемся пополам в тазобедренных суставах.", descriptionEn = "Drawing the feet closer, place the palms on the soles and grip the heels with the fingers, pressing the toes with the forearms. Push the pelvis away from the head and fold in half at the hip joints.",
            figure = FigureRef("baddhaup", false)),
        Asana(id = "at_freeup", nameRu = "Свободный перевёрнутый закрытый вытянутый наклон", nameEn = "Free inverted closed extended bend", pose = p(0, 0, 180, 180, 48, 48, 138, 47, 47, 138, 179, 179, 0),
            cuesRu = listOf("Руки вдоль тела, прямые ноги к груди, носки оттянуты."), sanskrit = null, descriptionRu = "Руки прямые вдоль тела ладонями вниз, носки оттянуты, жёстко прямые ноги изо всех сил прижимаем к груди.", descriptionEn = "Arms straight along the body, palms down, toes pointed, press the rigidly straight legs to the chest with all your strength.",
            figure = FigureRef("freeup", false)),
        Asana(id = "at_sarvanga", nameRu = "Простая стойка на плечах с поддержкой", nameEn = "Simple supported shoulderstand", pose = p(270, 0, 180, 70, 90, 90, 90, 91, 91, 90, 178, 68, 270),
            cuesRu = listOf("Махом всё тело вертикально, ладони у лопаток; стоять на плечах, шея свободна."), sanskrit = "саламба-сарвангасана", descriptionRu = "Плавным махом выпрямляем всё тело вертикально вверх, ладони ставим на спину ближе к лопаткам. Опора — плечи и плечевые части рук, шея и голова свободны; подбородок к груди не «накатываем» силой. Локти не шире плеч.", descriptionEn = "With a smooth swing, straighten the whole body vertically up, placing the palms on the back closer to the shoulder blades. The support is the shoulders and upper arms, neck and head free; do not force the chin onto the chest. Elbows no wider than the shoulders.",
            figure = FigureRef("sarvanga", false)),
        Asana(id = "at_ardhasarv", nameRu = "Полустойка на плечах с поддержкой", nameEn = "Supported half shoulderstand", pose = p(270, 0, 180, 70, 320, 320, 350, 321, 321, 350, 178, 68, 270),
            cuesRu = listOf("Прямые ноги за голову до касания пола носками.", "Прямые ноги за голову, носки на пол."), sanskrit = "ардха-саламба-сарвангасана", descriptionRu = "Не меняя положения туловища и почти не наклоняя таз, медленно опускаем прямые ноги за голову до касания пола оттянутыми носками.", descriptionEn = "Without changing the position of the torso and barely tilting the pelvis, slowly lower the straight legs behind the head until the pointed toes touch the floor.",
            figure = FigureRef("ardhasarv", false)),
        Asana(id = "at_urdhvahala", nameRu = "Вертикальный плуг", nameEn = "Vertical plough", pose = p(270, 0, 180, 180, 320, 320, 350, 321, 321, 350, 179, 179, 270),
            cuesRu = listOf("Руки назад, вывернутый замок прижат к полу."), sanskrit = "урдхва-халасана", descriptionRu = "Прямые руки вытягиваем назад, складываем в вывернутый замок и прижимаем к полу. Позвоночник тянется от плеч вверх к копчику, макушка — от тела. Носки на себя.", descriptionEn = "Extend the straight arms back, join them in a reversed lock and press them to the floor. The spine reaches from the shoulders up to the tailbone, the crown away from the body. Toes toward you.",
            figure = FigureRef("urdhvahala", false, hands = HandShape.LOCK)),
        Asana(id = "at_sarvquad", nameRu = "Растягивание бёдер в стойке на плечах", nameEn = "Hip stretch in shoulderstand", pose = p(270, 0, 180, 70, 90, 240, 240, 91, 242, 242, 178, 68, 270),
            cuesRu = listOf("Ноги вверх, согнуть, стопы назад; колени вместе, бёдра и торс в одной плоскости."), sanskrit = null, descriptionRu = "В стойке на плечах сгибаем ноги, оттягиваем носки и опускаем стопы как можно дальше назад. Колени вместе, передняя поверхность бёдер и торса — одна плоскость.", descriptionEn = "In shoulderstand, bend the legs, point the toes and lower the feet as far back as possible. Knees together, the fronts of the thighs and torso form one plane.",
            figure = FigureRef("sarvquad", false)),
        Asana(id = "at_sarvone", nameRu = "Полустойка на плечах, одна нога вверху", nameEn = "Half shoulderstand, one leg up", pose = p(270, 0, 180, 70, 320, 320, 350, 90, 90, 90, 178, 68, 270),
            cuesRu = listOf("Одну ногу махом вертикально вверх."), sanskrit = null, descriptionRu = "Из полустойки на плечах плавным махом поднимаем одну ногу вертикально; вторая остаётся носком на полу за головой.", descriptionEn = "From the half shoulderstand, with a smooth swing, raise one leg vertically; the other stays with its toes on the floor behind the head.",
            figure = FigureRef("sarvone", false)),
        Asana(id = "at_sarvonebent", nameRu = "Растягивание передней поверхности бедра в полустойке", nameEn = "Front-thigh stretch in half shoulderstand", pose = p(270, 0, 180, 70, 320, 320, 350, 90, 240, 240, 178, 68, 270),
            cuesRu = listOf("Согнуть поднятую ногу до предела, торс и бедро не смещать."), sanskrit = null, descriptionRu = "Поднятую ногу до предела сгибаем, растягивая переднюю поверхность бедра; положение торса и второй ноги не меняется.", descriptionEn = "Bend the raised leg to the limit, stretching the front of the thigh; the position of the torso and the other leg does not change.",
            figure = FigureRef("sarvonebent", false)),
        Asana(id = "at_sarvone_m", nameRu = "Полустойка на плечах, одна нога вверху", nameEn = "Half shoulderstand, one leg up", pose = p(270, 0, 178, 68, 90, 90, 90, 320, 320, 350, 180, 70, 270),
            cuesRu = listOf("Одну ногу махом вертикально вверх."), sanskrit = null, descriptionRu = "Из полустойки на плечах плавным махом поднимаем одну ногу вертикально; вторая остаётся носком на полу за головой.", descriptionEn = "From the half shoulderstand, with a smooth swing, raise one leg vertically; the other stays with its toes on the floor behind the head.",
            figure = FigureRef("sarvone", true)),
        Asana(id = "at_sarvonebent_m", nameRu = "Растягивание передней поверхности бедра в полустойке", nameEn = "Front-thigh stretch in half shoulderstand", pose = p(270, 0, 178, 68, 90, 240, 240, 320, 320, 350, 180, 70, 270),
