            figure = FigureRef("sarvonebent", true)),
        Asana(id = "at_sbridgek", nameRu = "Плечевой полумост с поддержкой", nameEn = "Supported shoulder half bridge", pose = p(310, 0, 180, 60, 175, 265, 180, 174, 266, 180, 178, 58, 290),
            cuesRu = listOf("Прогнувшись, стопы на пол; ладони в спину у почек, локти близко."), sanskrit = "ардха-сарванга-сету-бандхасана", descriptionRu = "Из стойки на плечах прогибаемся назад и ставим стопы на пол. Ладони упираются в спину на уровне почек пальцами наружу, локти близко; руками вытягиваем позвоночник вверх от плеч.", descriptionEn = "From shoulderstand, arch back and place the feet on the floor. The palms support the back at kidney level, fingers out, elbows close; use the hands to lengthen the spine up from the shoulders.",
            figure = FigureRef("sbridgek", false)),
        Asana(id = "at_sbridge", nameRu = "Плечевой мост с поддержкой", nameEn = "Supported shoulder bridge", pose = p(320, 0, 180, 60, 205, 205, 90, 206, 206, 90, 178, 58, 300),
            cuesRu = listOf("Выпрямить ноги, носки на себя.", "Выпрямить ноги вправо."), sanskrit = "сарванга-сету-бандхасана", descriptionRu = "В плечевом мосту с поддержкой выпрямляем ноги, растягиваем их заднюю поверхность, носки на себя.", descriptionEn = "In the supported shoulder bridge, straighten the legs, stretch their backs, toes toward you.",
            figure = FigureRef("sbridge", false)),
        Asana(id = "at_sbridgek1", nameRu = "Плечевой мост на одной ноге (левая опора)", nameEn = "One-leg shoulder bridge (left support)", pose = p(320, 0, 180, 60, 30, 210, 230, 206, 206, 90, 178, 58, 300),
            cuesRu = listOf("Правое колено к груди."), sanskrit = "эка-пада-сарванга-сету-бандхасана", descriptionRu = "Не меняя положения тела, сгибаем одну ногу и подтягиваем колено к груди; носки оттянуты.", descriptionEn = "Without changing the body position, bend one leg and draw the knee to the chest; toes pointed.",
            figure = FigureRef("sbridgek1", false)),
        Asana(id = "at_sbridgeup", nameRu = "Плечевой мост на одной ноге, другая вверх", nameEn = "One-leg shoulder bridge, other leg up", pose = p(320, 0, 180, 60, 90, 90, 0, 206, 206, 90, 178, 58, 300),
            cuesRu = listOf("Правую ногу вертикально, носок на себя."), sanskrit = "урдхва-эка-пада-сарванга-сету-бандхасана", descriptionRu = "Согнутую ногу выпрямляем вертикально вверх, носок на себя.", descriptionEn = "Straighten the bent leg vertically up, toes toward you.",
