            cuesRu = listOf("Не меняя положения тела, сгибаем одну ногу и подтягиваем колено к груди; носки оттянуты"), sanskrit = null, descriptionRu = "Не меняя положения тела, сгибаем одну ногу и подтягиваем колено к груди; носки оттянуты.", descriptionEn = "Without changing the body position, bend one leg and draw the knee to the chest; toes pointed.",
            figure = FigureRef("sbridgek1", true)),
        Asana(id = "at_sbridgeup_m", nameRu = "Плечевой мост на одной ноге, другая вверх", nameEn = "One-leg shoulder bridge, other leg up", pose = p(320, 0, 178, 58, 206, 206, 90, 90, 90, 0, 180, 60, 300),
